export type MessageKey = typeof messageRegistry.messages[number]['key'];
export type SiteMessages = Record<MessageKey, string>;
export function initialMessages(locale: string, defaultLocale = 'fr'): SiteMessages {
  return Object.fromEntries(messageRegistry.messages.map(message => {
    const initial: Readonly<Record<string, string>> = message.initial;
    return [message.key, initial[locale] ?? initial[defaultLocale] ?? initial.fr];
  })) as SiteMessages;
}
